import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';
import fs from 'fs';
import path from 'path';

// Discover SSL certificates generated by the signaling server for HTTPS support
const certCandidates = [
  path.resolve(__dirname, '../server/certificates'),
  path.resolve(process.cwd(), 'apps/server/certificates'),
  path.resolve(process.cwd(), 'certificates')
];

let httpsConfig: { key: Buffer; cert: Buffer } | undefined = undefined;

for (const dir of certCandidates) {
  const keyPath = path.join(dir, 'server.key');
  const certPath = path.join(dir, 'server.crt');
  if (fs.existsSync(keyPath) && fs.existsSync(certPath)) {
    httpsConfig = {
      key: fs.readFileSync(keyPath),
      cert: fs.readFileSync(certPath)
    };
    break;
  }
}

export default defineConfig({
  plugins: [react()],
  server: {
    host: '0.0.0.0',
    port: 5173,
    https: httpsConfig,
    proxy: {
      '/api': {
        target: 'https://localhost:3000',
        secure: false, // Allow self-signed SSL cert in dev
        changeOrigin: true
      },
      '/socket.io': {
        target: 'https://localhost:3000',
        secure: false,
        ws: true,
        changeOrigin: true
      }
    }
  }
});
